import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Create plane geometry with 16:10 aspect ratio
  const geometry = new THREE.PlaneGeometry(2, 1.25);

  // Load texture from imageUrl
  const textureMap = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material using MeshBasicNodeMaterial
  const material = new MeshBasicNodeMaterial({
    map: textureMap,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config
  const position = config.scenePosition || { x: 3.2, y: -0.3, z: 0 };
  const rotation = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scale = config.sceneScale || { x: 1, y: 1, z: 1 };

  mesh.position.set(position.x, position.y, position.z);
  mesh.rotation.set(rotation.x, rotation.y, rotation.z);
  mesh.scale.set(scale.x, scale.y, scale.z);

  // Store original transform for animations
  const originalPos = mesh.position.clone();
  const originalScale = mesh.scale.clone();

  // Initialize event handlers
  mesh.userData.handlers = {};

  // Hover: rise-in animation (0.15 scene units up)
  mesh.userData.handlers.onHover = () => {
    gsap.killTweensOf(mesh.position);
    gsap.to(mesh.position, {
      y: originalPos.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  mesh.userData.handlers.onHoverOut = () => {
    gsap.killTweensOf(mesh.position);
    gsap.to(mesh.position, {
      y: originalPos.y,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click: press-down animation and emit event
  mesh.userData.handlers.onClick = () => {
    gsap.killTweensOf(mesh.scale);

    gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    });

    gsap.to(mesh.scale, {
      x: originalScale.x,
      y: originalScale.y,
      z: originalScale.z,
      delay: 0.12,
      duration: 0.08,
      ease: 'back.out'
    });

    if (ctx.emit) {
      ctx.emit('hub-journal.select', {});
    }
  };

  // Focus: accent edge highlight in signal red
  let accentEdge = null;

  mesh.userData.handlers.onFocus = () => {
    if (!accentEdge) {
      const edges = new THREE.EdgesGeometry(geometry);
      const line = new THREE.LineSegments(
        edges,
        new THREE.LineBasicMaterial({
          color: 0xff2a38,
          linewidth: 2
        })
      );
      mesh.add(line);
      accentEdge = line;
    }
  };

  mesh.userData.handlers.onBlur = () => {
    if (accentEdge) {
      mesh.remove(accentEdge);
      accentEdge.geometry.dispose();
      accentEdge.material.dispose();
      accentEdge = null;
    }
  };

  // Cleanup function
  mesh.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);

    if (accentEdge) {
      mesh.remove(accentEdge);
      accentEdge.geometry.dispose();
      accentEdge.material.dispose();
    }

    geometry.dispose();
    material.dispose();
    textureMap.dispose();

    mesh.userData.handlers = {};
  };

  return mesh;
}
